import{validImageSettings}from'./card-images.mjs';
export const MODES={nyan:{label:'にゃんうぉ用',count:1},arena:{label:'闘技場用',count:4},incident:{label:'怪異事件用',count:4}};
export const blank=m=>Array.from({length:MODES[m].count},()=>Array(6).fill(null));
export const fresh=()=>({version:1,owned:{},favorites:[],current:Object.fromEntries(Object.keys(MODES).map(m=>[m,blank(m)])),builds:[]});
export const powerOK=p=>Number.isInteger(p)&&p>=1&&p<=9999;
export const total=s=>s.flat().reduce((n,c)=>n+(c?.power||0),0);
export function validSquads(s,m,ids){if(!Array.isArray(s)||s.length!==MODES[m]?.count)throw Error('班数が正しくありません');return s.map(row=>{if(!Array.isArray(row)||row.length!==6)throw Error('カード枠が正しくありません');const seen=new Set();return row.map(c=>{if(c===null)return null;if(!c||!ids.has(c.id)||!powerOK(c.power)||seen.has(c.id))throw Error('カード・戦力・班内の重複を確認してください');seen.add(c.id);return{id:c.id,power:c.power}})})}
export function validBuild(b,ids){if(!b||!MODES[b.mode]||typeof b.name!=='string'||!b.name.trim()||b.name.length>80)throw Error('ビルドの形式が正しくありません');return{id:typeof b.id==='string'?b.id:crypto.randomUUID(),name:b.name,mode:b.mode,squads:validSquads(b.squads,b.mode,ids),updatedAt:typeof b.updatedAt==='string'?b.updatedAt:new Date().toISOString()}}
export function validState(v,ids){if(v?.version!==1||!v.owned||!v.current||!Array.isArray(v.builds))throw Error('対応していないバックアップです');const s=fresh();if(v.favorites!==undefined){if(!Array.isArray(v.favorites)||v.favorites.some(id=>!ids.has(id))||new Set(v.favorites).size!==v.favorites.length)throw Error('お気に入りが正しくありません');s.favorites=[...v.favorites];}for(const [id,p]of Object.entries(v.owned)){if(!ids.has(Number(id))||!powerOK(p))throw Error('手持ちデータが正しくありません');s.owned[id]=p}for(const m of Object.keys(MODES))s.current[m]=validSquads(v.current[m],m,ids);if(v.imageSettings!==undefined)s.imageSettings=validImageSettings(v.imageSettings,ids);s.builds=v.builds.map(b=>validBuild(b,ids));if(new Set(s.builds.map(b=>b.id)).size!==s.builds.length)throw Error('ビルドIDが重複しています');return s}
export async function encodeShare(builds){const compact={v:1,b:builds.map(b=>[b.name,b.mode,b.squads.map(r=>r.map(c=>c?[c.id,c.power]:null))])};const bytes=new TextEncoder().encode(JSON.stringify(compact));let data=bytes,prefix='j';if(typeof CompressionStream!=='undefined'){data=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());prefix='z'}return prefix+btoa(String.fromCharCode(...data)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}
export async function decodeShare(token,ids){if(token.length>100000)throw Error('共有データが大きすぎます');if(!/^[jz][\w-]+$/.test(token))throw Error('共有リンクが正しくありません');const bytes=Uint8Array.from(atob(token.slice(1).replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0));let stream=new Blob([bytes]).stream();if(token[0]==='z')stream=stream.pipeThrough(new DecompressionStream('gzip'));const reader=stream.getReader();let size=0,chunks=[];while(true){const {value,done}=await reader.read();if(done)break;size+=value.length;if(size>300000){await reader.cancel();throw Error('共有データが大きすぎます')}chunks.push(value)}const v=JSON.parse(await new Blob(chunks).text());if(v.v!==1||!Array.isArray(v.b)||v.b.length>10)throw Error('共有形式が正しくありません');return v.b.map(b=>validBuild({name:b[0],mode:b[1],squads:b[2].map(r=>r.map(c=>c?{id:c[0],power:c[1]}:null))},ids))}
